import{z as o,x as A,o as r,c as B,q as t,j as l,D as e,d as i,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"多机位 reframing 与子弹时间","description":"","frontmatter":{"title":"多机位 reframing 与子弹时间","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/atlas-video-reframe.md","filePath":"llm/atlas-video-reframe.md","lastUpdated":1791063341000}'),p={name:"llm/atlas-video-reframe.md"};function d(m,a,_,f,h,C){const E=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=t('<h1 id="多机位-reframing-与子弹时间" tabindex="-1">多机位 reframing 与子弹时间 <a class="header-anchor" href="#多机位-reframing-与子弹时间" aria-label="Permalink to &quot;多机位 reframing 与子弹时间&quot;">​</a></h1><div class="epigraph"><p>三五部普通手机，配上三脚架和背包里能装下的夹具，就可以把一场真实发生的动作改机位、甚至冻住时间；不需要环形相机棚。</p><footer>—— 改写自 World Labs Team, Atlas, 2026</footer></div><p>相机可控生成往往从静图出发，沿一条虚拟路径长出世界。Reframing 方向相反：时间轴上已经有真实事件，只是机位不够多。用户想要的是同一场戏里换一个看不见的摄影机——侧看、俯看、甚至环绕的子弹时间。Atlas 把这件事情收在「时空仿真」下：先从三到五路普通摄像机重建场景，再在同一时空里查询新相机。本篇只写「同一场景改机位」，不把从零生成的一分钟镜头算进 reframing，也不把机器人传感器仿真展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典子弹时间依赖密集环形阵列、快门同步和后期插值。成本把效果锁在广告与电影工业里。消费级拍摄通常只有两三个固定机位，中间视角没有光线采样。光流或深度扭曲可以在基线很小时糊弄过去，人物一转、遮挡一出现，重影和撕裂就来了。</p><p>问题可以写成：给定同一时刻附近的稀疏相机 \\(\\{I_i(t), P_i\\}\\)，求新相机 \\(P_*\\) 上的 \\(I_*(t)\\)，并允许把 \\(t\\) 钉死，只动 \\(P_*\\)——这就是冻时环绕。约束是事件本身（谁站在哪、手臂抬到哪）应尽量来自观测，而不是再编一场戏。这与单图生成「背面可以猜」不同：猜错人脸或运动相位，在叙事上比猜错一栋房子更致命。</p><h3 id="改机位不是另拍一条视频" tabindex="-1">改机位不是另拍一条视频 <a class="header-anchor" href="#改机位不是另拍一条视频" aria-label="Permalink to &quot;改机位不是另拍一条视频&quot;">​</a></h3><p>若把每路手机视频分别送进文本视频模型做「换角度」，模型会另生成一段动作，时间线和主体身份都会漂。Reframing 要求动作是同一场：新机位是查询，不是重新采样一条时间。空间上下文里必须同时有多路、同时刻（或准同时刻）的观测，模型才能把「事件」和「观察者」拆开。</p><p><span class="marginnote">官方镜头「并不需要职业摄影师或特种棚」，指捕获端。输出端的新角度仍然是模型生成的像素，不是那一角度上的真实感光。新闻、取证、监控场景里，生成机位不能当证据。VFX 与预演可以，法庭与纪录必须分开说。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>捕获：三到五台手机或运动相机，固定在三脚架或夹具上，同步拍同一场。Atlas 从这些视图重建场景——几何来自多视，外观与运动来自视频。查询：指定新的 \\(P_*\\)，或指定一条只改观察者、少改时间的路径。冻时（bullet time）对应 \\(t\\) 固定、\\(P\\) 沿弧运动；普通 reframing 可以 \\(t\\) 继续走，只是机位换成侧拍或更近的镜头。</p><p>实现上仍是带位姿的序列：每一路真实视频是图像元素流，每帧有自己的 \\(P_i\\)。新机位作为后续元素的条件被插入。深度可以一并写出，便于检查遮挡。World Labs 强调这些示例是工程师用消费设备拍的，目的是把「多机位工作室」从硬件搬到模型的空间上下文容量上。</p>',12)),(r(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E7%9B%B8%E6%9C%BA%20A%20%E5%AE%9E%E6%8B%8D%22%5D%20--%3E%20REC%5B%22%E7%A8%80%E7%96%8F%E5%A4%9A%E8%A7%86%E9%87%8D%E5%BB%BA%22%5D%0A%20%20C2%5B%22%E7%9B%B8%E6%9C%BA%20B%20%E5%AE%9E%E6%8B%8D%22%5D%20--%3E%20REC%0A%20%20C3%5B%22%E7%9B%B8%E6%9C%BA%20C%20%E5%AE%9E%E6%8B%8D%22%5D%20--%3E%20REC%0A%20%20REC%20--%3E%20T%5B%22%E5%85%B1%E4%BA%AB%E6%97%B6%E7%A9%BA%22%5D%0A%20%20T%20--%3E%20Q1%5B%22%E6%96%B0%E6%9C%BA%E4%BD%8D%E8%BF%9E%E7%BB%AD%E6%97%B6%E9%97%B4%22%5D%0A%20%20T%20--%3E%20Q2%5B%22%E5%86%BB%E7%BB%93%20t%20%E7%8E%AF%E7%BB%95%20P%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="时间钉死与空间插值" tabindex="-1">时间钉死与空间插值 <a class="header-anchor" href="#时间钉死与空间插值" aria-label="Permalink to &quot;时间钉死与空间插值&quot;">​</a></h3><p>子弹时间把观察者从时间轴上解耦。记真实机位在 \\(t_0\\) 的观测为 \\(I(P_i,t_0)\\)，查询是</p> \\[I(P_*,t_0) \\;\\sim\\; p\\bigl(\\,\\cdot\\mid \\{I(P_i,t_0)\\}_i,\\; P_*\\bigr), \\]<p>即固定时刻、只换 \\(P_*\\)。若各机未完美同步，实际用的是一个小窗口 \\([t_0-\\delta,t_0+\\delta]\\) 里最近的帧，误差表现为「冻住的人」微动或错位。空间上，\\(P_*\\) 若落在真实相机凸包内，更像插值；若落到凸包外（飞到演员背后而上边没有机），又变成有时间锚的稀疏生成。官方没有给出同步容差与滚动快门的处理细节，方法层应把多机时间对齐当成前置条件，而不是假设模型内部有完整的高帧同步器。</p><p><span class="marginnote">直觉类比：凸包像几台相机围出的一顶「帐篷」。查询机位在帐篷里，等于从不同角度的真实观测之间做插值，稳；飞到帐篷外，模型只能靠想象把画面接出去——「冻结的人」开始有编的成分。</span></p><p><span class="marginnote">为什么多机同步是前置条件：三台手机时间码差半帧，快速动作下各机看到的肢体位置就不同，模型拿到的是「同一时刻」的假象。轻则冻结的人微抖，重则手臂在新视角里分叉。这是捕获端的活，模型替不了。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同一场景改机位，依赖模型把内容因子与相机因子分开。若表示纠缠，改 \\(P\\) 会改动作。空间上下文把各路图像钉在三维位置上，相当于告诉注意力：这些像素是同一世界点的不同投影。查询新 \\(P_*\\) 时，已见投影提供外观，几何提供遮挡顺序。冻时则切断时间维的生成自由度，只沿相机流形采样。</p><p>与<a href="/llm/atlas-sparse-view-recon">稀疏新视角合成</a> 的差别在于时间。静态建筑重建可以东补一块西补一块；动作 reframing 必须在同一 \\(t\\) 上自洽。手臂遮住脸时，新机位看到的应是那一帧的遮挡关系，而不是另一帧的抬手。这要求上下文能索引「时刻」而不只是「地点」。Atlas 把视频当作图像序列，时间通过序列顺序与（可能的）位姿时间戳进入模型；内部是否有显式 \\(t\\) 标记，发布说明未写。能确定的是任务编排：输入是多路真实视频，输出是新观察者。</p><p><span class="marginnote">三机已经能出演示级环绕，不表示任意运动相位都能插。快速挥拍、运动模糊、滚动快门会让同一 \\(t_0\\) 上的多机图像互不一致，模型只能折中。折中看起来像「还能看」，计量上却可能把轨迹插错。</span></p><h3 id="为何不是光流扭曲" tabindex="-1">为何不是光流扭曲 <a class="header-anchor" href="#为何不是光流扭曲" aria-label="Permalink to &quot;为何不是光流扭曲&quot;">​</a></h3><p>平面光流假设亮度恒定、遮挡很少。多机位人物场景里，基线大、自遮挡多，光流没有正确的对应。体积方法或溅射可以在静态场上插值，动态场则要 4D 表示或逐帧重建。Atlas 走生成式世界模型：用先验填上光流填不上的洞，同时用真实多机把先验锁在这场戏上。收益是设备极简；代价是「中间机位」含有生成成分，极端 \\(P_*\\) 上身份可能漂。</p>',12)),(r(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BB%8E%E7%9C%9F%E5%AE%9E%E5%A4%9A%E6%9C%BA%E4%BD%8D%E5%87%BA%E6%96%B0%E6%9C%BA%E4%BD%8D%E8%A7%86%E8%A7%92%22%5D%0A%20%20Q%20--%3E%20F%5B%22%E5%85%89%E6%B5%81%E6%89%AD%E6%9B%B2%5Cn%E5%B0%8F%E5%9F%BA%E7%BA%BF%E5%8F%AF%E7%94%A8%5Cn%E5%A4%A7%E9%81%AE%E6%8C%A1%E5%8D%B3%E6%92%95%E8%A3%82%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E6%BA%85%E5%B0%84%20%2F%20%E4%BD%93%E7%A7%AF%E6%8F%92%E5%80%BC%5Cn%E9%9D%99%E6%80%81%E5%9C%BA%E7%A8%B3%5Cn%E5%8A%A8%E6%80%81%E5%9C%BA%E9%9C%80%204D%20%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20Q%20--%3E%20G%5B%22Atlas%EF%BC%9A%E7%94%9F%E6%88%90%E5%BC%8F%E4%B8%96%E7%95%8C%E6%A8%A1%E5%9E%8B%5Cn%E5%85%88%E9%AA%8C%E8%A1%A5%E6%B4%9E%20%2B%20%E5%A4%9A%E6%9C%BA%E9%94%81%E6%AD%BB%E8%BF%99%E5%9C%BA%E6%88%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">数字实例：2 台相机只有一条基线，深度靠猜的成分大；3 台起才有「面」上的多视约束。从 2 机加到 5 机，凸包体积与覆盖角度成倍增长，插值区变大、生成区变小——加机位就是在用观测换想象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Reframing 不创造新的事件，只改观察者——这是意图，不是保证。主体换脸、衣服纹理循环、冻结时的肢体抖动，都是可见风险。机位数少于三时，立体约束弱，子弹时间更容易退化成「围着一张深度图转」。多于五路当然更好，但官方把叙事放在「背包捕获」；工程上应按场景复杂度加机，而不是把三当魔法数。</p><p>同步、标定、色彩一致性仍是捕获端的活。模型不能从三路未标定竖屏视频里变出电影级光轴。发布材料没有谈音频、也没有谈口型随新机位的变化；这条能力是视觉时空，不是虚拟制作全栈。动态范围极大（舞台灯）或几乎无纹理的墙，多视匹配会失败，生成会接管，看起来光滑却无几何依据。</p><p><span class="marginnote">与相机可控长视频的分工：长视频常从静图或少量静帧「长出」尚未发生的运动与空间；reframing 假定运动已经发生，只缺机位。产品里若把生成的动作片段再拿去「换机位」，应先声明时间轴是合成的，避免和真实多机 reframing 混用同一套验收。</span></p><p>版权与肖像：改机位会露出实拍里没有的身体侧面，那些像素是生成的，但仍可能被认成真人。商用前要按生成媒体而不是按「另一个机位的素材带」来授权。早鸟模型的延迟未知，实时导播级 reframing 并未被声称。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reframing 与子弹时间是同一时空里改观察者：前者时间可走，后者可把 \\(t\\) 钉死只动 \\(P\\)。</li><li>Atlas 用三到五路消费级相机重建后再查询新机位，意图是去掉环形棚。</li><li>新角度是生成像素，即使几何被真实多机锚定；证据场景不适用。</li><li>与从静图生成长镜头不同，这里的时间轴来自实拍事件。</li><li>同步、标定、快运动与凸包外机位是主要质量边界。</li><li>三机是演示起点，不是对所有动作相位的充分采样。</li><li>出处：World Labs Team，<em>Atlas: A World Model for Spatial Intelligence</em>，World Labs Blog，2026。</li></ul>',8))])}const P=o(p,[["render",d]]);export{D as __pageData,P as default};
